class Solution:
    def convert(self, s: str, numRows: int) -> str:
        if numRows == 1 or numRows >= len(s):
            return s
        grid = [[""] * len(s) for _ in range(numRows)]
        row, col, direction = 0, 0, 1
        for ch in s:
            grid[row][col] = ch
            if direction == 1:
                if row == numRows - 1:
                    direction = -1
                    row -= 1
                    col += 1
                else:
                    row += 1
            else:
                if row == 0:
                    direction = 1
                    row += 1
                else:
                    row -= 1
                    col += 1
        return ''.join(ch for line in grid for ch in line if ch)

solutions.better:
class Solution:
    def convert(self, s: str, numRows: int) -> str:
        if numRows == 1 or numRows >= len(s):
            return s
        rows = [[] for _ in range(numRows)]
        row, step = 0, 1
        for ch in s:
            rows[row].append(ch)
            if row == 0:
                step = 1
            elif row == numRows - 1:
                step = -1
            row += step
        return ''.join(''.join(line) for line in rows)

